// ===== 取 5 个节点返回的记录 =====
function recordsOf(nodeName) {
  try {
    const it = $(nodeName).first().json;
    if (Array.isArray(it.items)) return it.items;
    if (Array.isArray(it)) return it;
    return [];
  } catch (e) { return []; }
}

function core(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number' || typeof v === 'boolean') return v;
  if (typeof v === 'string') return v.trim() || null;
  if (Array.isArray(v)) {
    const a = v.map(core).filter(x => x !== null);
    return a.length === 1 ? a[0] : a;
  }
  if (typeof v === 'object') {
    for (const k of ['text', 'name', 'value', 'link', 'url']) {
      if (v[k] !== undefined && v[k] !== null) return core(v[k]);
    }
    if (v.values !== undefined) return core(v.values);
  }
  return String(v);
}

function flat(fields) {
  const out = {};
  for (const [k, v] of Object.entries(fields || {})) {
    const key = String(k).trim();
    let val = core(v);
    if (typeof val === 'number' && val > 1e11 && /(日期|时间)$/.test(key)) {
      val = new Date(val).toISOString().slice(0, 10);
    }
    out[key] = val;
  }
  return out;
}

const data = {
  '商品配置': recordsOf('商品配置').map(r => flat(r.fields)),
  '运价表':   recordsOf('运价表').map(r => flat(r.fields)),
  '全局参数': recordsOf('全局参数').map(r => flat(r.fields)),
  '国家规则': recordsOf('国家规则').map(r => flat(r.fields)),
  '澳洲分区': recordsOf('澳洲分区').map(r => flat(r.fields))
};

// ===== 体检 =====
const REQUIRED = {
  '商品配置': ['SKU前缀', '采购价', '国内运费', '重量'],
  '运价表':   ['国家', '下界', '上界', '公斤价', '挂号费'],
  '澳洲分区': ['邮编', '分区'],
  '全局参数': ['参数键', '参数值'],
  '国家规则': ['国家', '是否欧盟']
};
const problems = [];
for (const [t, cols] of Object.entries(REQUIRED)) {
  const rows = data[t] || [];
  if (!rows.length) { problems.push(`${t}: 0 条记录（表名 / 协作者 / bitable:app）`); continue; }
  const keys = Object.keys(rows[0]);
  const miss = cols.filter(c => !keys.includes(c));
  if (miss.length) problems.push(`${t}: 缺字段 ${JSON.stringify(miss)}`);
}
const seen = new Set(); const dup = [];
for (const r of data['商品配置'] || []) {
  const k = r['SKU前缀'];
  if (!k) continue;
  if (seen.has(k)) dup.push(k);
  seen.add(k);
}
if (dup.length) problems.push(`商品配置: SKU前缀重复 ${JSON.stringify([...new Set(dup)])}`);

if (problems.length) {
  throw new Error('飞书配置有问题：\n' + problems.join('\n'));
}

// ===== 输出一个 item，交给 MoveBinaryData 落盘 =====
return [{
  json: {
    config: data,
    fileName: $('配置').item.json.config_path,
    counts: Object.fromEntries(Object.entries(data).map(([k, v]) => [k, v.length]))
  }
}];

const r = $json;
const out = (r.stdout || '').trim();
const err = (r.stderr || '').trim();

if (r.code !== 0) {
  throw new Error('生成计算表失败：' + err.split('\n').slice(-6).join(' | '));
}
const line = out.split('\n').find(l => l.startsWith('RESULT '));
const result = line ? JSON.parse(line.slice(7)) : {};

return [{
  json: {
    ok: Boolean(result.ok),
    orders: result.orders,
    rows: result.rows,
    issues: result.issues,
    bill_total: result.bill_total,
    out: result.out,
    log: out.split('\n').slice(-6)
  }
}];
